def _time_basis(times, rates):
    return -np.expm1(-np.outer(times, rates))


def _temporal_fit(times, traj):
    def residual(rates):
        a = _time_basis(times, rates)
        return (a @ _fit(a, traj.T) - traj.T).ravel()

    rates = least_squares(residual, [1.8, .42],
